/* Types */
/**  What one operation needs. */
export type Access = 
/**  Read a file, list a directory, read metadata. */
"read" | 
/**  Modify an existing file. */
"write" | 
/**  Create a new file or directory. */
"create" | 
/**  Move or rename. */
"move" | 
/**  Move to the Trash. */
"trash";

export type ActivateResult = {
	id: string,
	/**  For example "This model has no chat template; replies may be poor." */
	warning: string | null,
};

export type AgeBuckets = {
	last_7d: AgeStat,
	last_30d: AgeStat,
	last_365d: AgeStat,
	older: AgeStat,
	unknown: AgeStat,
};

export type AgeStat = {
	files: number,
	bytes: number,
};

/**  Static facts about this install. */
export type AppInfo = {
	version: string,
	os: string,
	arch: string,
	data_dir: string,
	log_dir: string,
	/**  `None` in dev builds, which have no `bundle.json`. */
	build: BuildInfo | null,
};

